function geoNorm(v){
  return String(v||"").toLowerCase()
    .replace(/[’'`"]/g,"")
    .replace(/[\u200b-\u200f\u202a-\u202e]/g,"")
    .replace(/[।,;|()[\]{}]/g," ")
    .replace(/ড়/gu,"ড়").replace(/ঢ়/gu,"ঢ়")
    .replace(/\b(?:districts?|dist|zilla|jila)\b/gu,"")
    .replace(/\b(?:upzala|upazila|upazilla|thana|ps)\b/gu,"")
    .replace(/\b(?:division|divition|div)\b/gu,"")
    .replace(/\s+/g," ").trim();
}
function geoDigits(v){
  return String(v||"").replace(/[০-৯]/g,c=>"০১২৩৪৫৬৭৮৯".indexOf(c));
}
function geoDistance(a,b){
  a=geoNorm(a); b=geoNorm(b);
  if(a===b)return 0;
  if(!a||!b)return 99;
  const n=a.length,m=b.length;
  const dp=Array.from({length:n+1},()=>Array(m+1).fill(0));
  for(let i=0;i<=n;i++)dp[i][0]=i;
  for(let j=0;j<=m;j++)dp[0][j]=j;
  for(let i=1;i<=n;i++)for(let j=1;j<=m;j++)
    dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(a[i-1]===b[j-1]?0:1));
  return dp[n][m];
}
function geoBest(list,value){
  const q=geoNorm(value);
  if(!q||!Array.isArray(list)||!list.length)return null;
  let best=null,score=1e9;
  for(const x of list){
    for(const v of [x.bn,x.en]){
      const n=geoNorm(v);
      if(!n)continue;
      let s=geoDistance(q,n);
      if(n.includes(q)||q.includes(n))s-=Math.min(q.length,n.length)*0.25;
      if(s<score){score=s;best=x;}
    }
  }
  // Exact/containment matches are preferred. Fuzzy matching is deliberately
  // conservative so unrelated names such as "উসমানগঞ্জ" do not become
  // "গোপালগঞ্জ".
  const threshold=q.length<=4?1:Math.min(2,Math.floor(q.length*0.28));
  return score<=threshold?best:null;
}
function geoAll(){
  return ADDRESS_GEO_DATA.districts||[];
}
function geoFindDistrict(value){
  const q=geoNorm(value);
  if(!q)return null;
  const exact=geoAll().find(x=>geoNorm(x.bn)===q||geoNorm(x.en)===q);
  return exact||geoBest(geoAll(),value);
}
function geoFindUpazila(value,district){
  const list=district?district.upazilas:geoAll().flatMap(d=>d.upazilas.map(u=>({...u,_district:d})));
  const q=geoNorm(value);
  if(!q)return null;
  const exact=list.find(x=>geoNorm(x.bn)===q||geoNorm(x.en)===q);
  return exact||geoBest(list,value);
}
function geoFindUnion(value,upazila){
  if(!upazila)return null;
  const q=geoNorm(value);
  if(!q)return null;
  const exact=upazila.unions.find(x=>geoNorm(x.bn)===q||geoNorm(x.en)===q);
  return exact||geoBest(upazila.unions,value);
}
function geoFirst(a){return Array.isArray(a)&&a.length?a[0]:null;}

function geoAddressDefaults(target){
  const out=target||{};
  if(!out.country)out.country="1";
  if(!out.ward)out.ward=ADDRESS_GEO_DATA.defaults.ward;
  if(!out.villageBn)out.villageBn=ADDRESS_GEO_DATA.defaults.villageBn;
  if(!out.villageEn)out.villageEn=ADDRESS_GEO_DATA.defaults.villageEn;
  if(!out.postOfficeBn)out.postOfficeBn=ADDRESS_GEO_DATA.defaults.postOfficeBn;
  if(!out.postOfficeEn)out.postOfficeEn=ADDRESS_GEO_DATA.defaults.postOfficeEn;
  return out;
}

function geoExtractAddress(raw){
  let source=String(raw||"");
  // Keep the address block isolated from birth-place/person information.
  const am=source.match(/(?:জন্ম\s*স্থানের\s*ঠিকানা|জন্মস্থান|জন্ম\s*স্থান|place\s*of\s*birth|birth\s*place|স্থায়ী\s*ঠিকানা|স্থায়ী\s*ঠিকানা|স্থায়ী\s*ও\s*বর্তমান\s*ঠিকানা|permanent\s*address|present\s*address|ঠিকানা)\s*[:：=ঃ\-]?([\s\S]*)$/iu);
  if(am && am[1])source=am[1];
  const lines=source.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  const a={division:"",district:"",upazila:"",union:"",ward:"",villageBn:"",villageEn:"",
    postOfficeBn:"",postOfficeEn:"",postCode:"",houseRoadBn:"",houseRoadEn:""};
  const allText=lines.join(" ");
  const put=(k,v)=>{v=String(v||"").trim(); if(v && !a[k])a[k]=v;};

  for(let i=0;i<lines.length;i++){
    let line=lines[i].replace(/^[★♦️•●▪️\-\s]+|[★♦️•●▪️\-\s]+$/gu,"").trim();
    let m=line.match(/^(.*?)\s*[:：=ঃ\-]\s*(.*?)\s*$/u);
    if(m){
      const l=m[1].trim(),rawV=m[2].trim();
      if(!rawV)continue;
      // When multiple address fields share one line, e.g.
      // "গ্রাম: মানিকা, পোস্ট: চরন্তী, জেলা: ভোলা", only the value before
      // the next comma belongs to the current label.
      const v=rawV.split(/[,;|]+/)[0].trim();
      if(!v)continue;
      if(/(?:বিভাগ|division|divition|div\b)/iu.test(l))put("division",v);
      else if(/^(?:জেলা|district|districts|zilla)$/iu.test(l) || /(?:^|\s)(?:district|districts|zilla)\s*(?:no)?$/iu.test(l))put("district",v);
      else if(/(?:উপজেলা|upzala|upazila|upazilla|thana|ps)/iu.test(l))put("upazila",v);
      else if(/(?:ইউনিয়ন|ইউনিয়ন|union|pourashava|municipality)/iu.test(l))put("union",v);
      else if(/(?:ওয়ার্ড|ওয়ার্ড|ward|word\s*no)/iu.test(l))put("ward",geoDigits(v).replace(/\D/g,"")||v);
      else if(/(?:গ্রাম|village|vill)/iu.test(l))put(/^(?:village|vill)$/iu.test(l)?"villageEn":"villageBn",v);
      else if(/(?:ডাকঘর|post\s*office|postoffice|post\b)/iu.test(l))put(/^(?:post\s*office|postoffice|post)$/iu.test(l)?"postOfficeEn":"postOfficeBn",v);
      else if(/(?:post\s*code|postal\s*code|postcode|পোস্ট\s*কোড)/iu.test(l))put("postCode",geoDigits(v).replace(/[^\d-]/g,""));
    }
  }

  // Also parse inline address fields such as:
  // "জেলা: ভোলা, উপজেলা: ভোলা সদর, ইউনিয়ন: আলীনগর"
  // and mixed Bengali/English variants.
  const inlineParts=allText.split(/[,;|]+/).map(x=>x.trim()).filter(Boolean);
  for(const part of inlineParts){
    const mm=part.match(/^(.*?)\s*[:：=ঃ\-]\s*(.+)$/u);
    if(!mm)continue;
    const l=mm[1].trim(),v=mm[2].trim();
    if(!v)continue;

    if(/(?:বিভাগ|division|divition|div\b)/iu.test(l))put("division",v);
    else if(/^(?:জেলা|district|districts|zilla)$/iu.test(l) || /(?:^|\s)(?:district|districts|zilla)\s*(?:no)?$/iu.test(l))put("district",v);
    else if(/(?:উপজেলা|upzala|upazila|upazilla|thana|ps)/iu.test(l))put("upazila",v);
    else if(/(?:ইউনিয়ন|ইউনিয়ন|union|pourashava|municipality)/iu.test(l))put("union",v);
    else if(/(?:ওয়ার্ড|ওয়ার্ড|ward|word\s*no)/iu.test(l))put("ward",geoDigits(v).replace(/\D/g,"")||v);
    else if(/(?:গ্রাম|village|vill)/iu.test(l))put(/^(?:village|vill)$/iu.test(l)?"villageEn":"villageBn",v);
    else if(/(?:ডাকঘর|post\s*office|postoffice|post\b)/iu.test(l))put(/^(?:post\s*office|postoffice|post)$/iu.test(l)?"postOfficeEn":"postOfficeBn",v);
    else if(/(?:post\s*code|postal\s*code|postcode|পোস্ট\s*কোড)/iu.test(l))put("postCode",geoDigits(v).replace(/[^\d-]/g,""));
  }

  // Free-form comma-separated address: infer district/upazila/union/ward by geo matching.
  const candidates=allText.split(/[,()\\n]+/).map(x=>x.trim()).filter(x=>x.length>1);
  if(!a.district){
    // First pass: exact district names only.
    for(const c of candidates){
      const d=geoAll().find(x=>geoNorm(x.bn)===geoNorm(c)||geoNorm(x.en)===geoNorm(c));
      if(d){a.district=d.bn;break;}
    }
    // Second pass: conservative fuzzy match.
    if(!a.district){
      for(const c of candidates){const d=geoFindDistrict(c);if(d){a.district=d.bn;break;}}
    }
  }
  let d=geoFindDistrict(a.district)||geoAll().find(x=>x.bn===a.district||x.en===a.district);
  if(!d){
    for(const c of candidates){const u=geoFindUpazila(c);if(u&&u._district){d=u._district;a.upazila=u.bn;break;}}
  }
  if(d && !a.upazila){
    const u=geoFindUpazila(a.upazila,d);
    if(u)a.upazila=u.bn;
  }
  let u=d?geoFindUpazila(a.upazila,d):null;
  if(!u && d){
    for(const c of candidates){const uu=geoFindUpazila(c,d);if(uu){u=uu;a.upazila=uu.bn;break;}}
  }
  if(u && !a.union){
    const un=geoFindUnion(a.union,u);
    if(un)a.union=un.bn;
  }
  if(!a.union && u){
    for(const c of candidates){const un=geoFindUnion(c,u);if(un){a.union=un.bn;break;}}
  }
  if(d){
    a.division=a.division||d.divisionBn;
    a.district=d.bn;
    if(!a.upazila){
      const fu=geoFirst(d.upazilas);
      if(fu)a.upazila=fu.bn;
    }
  }
  if(u && !a.union){
    const fun=geoFirst(u.unions);
    if(fun)a.union=fun.bn;
  }
  return geoAddressDefaults(a);
}

function geoCompleteAddress(target,raw,kind){
  const src=geoExtractAddress(raw);
  const out=Object.assign({},target||{});
  const keys=["division","district","upazila","union","ward","area","villageBn","villageEn","postOfficeBn","postOfficeEn","postCode","houseRoadBn","houseRoadEn"];
  for(const k of keys)if(!out[k]&&src[k])out[k]=src[k];
  out.country=out.country||"1";

  // Resolve hierarchy again from the best known supplied value.
  let d=geoFindDistrict(out.district);
  if(!d){
    for(const x of ADDRESS_GEO_DATA.districts){
      if(x.divisionBn===out.division||x.divisionEn===out.division){d=x;break;}
    }
  }
  if(d){
    out.division=d.divisionBn;
    out.district=d.bn;
    // If only the district is supplied, use the first Geo Data upazila
    // for that district as the deterministic completion source. Once an
    // upazila is selected, every union lookup is restricted to that upazila.
    let u=geoFindUpazila(out.upazila,d);
    if(!u)u=geoFirst(d.upazilas);
    if(u){
      out.upazila=u.bn;
      let un=geoFindUnion(out.union,u);
      if(!un)un=geoFirst(u.unions);
      // IMPORTANT: a union must belong to the selected upazila.
      // Never borrow a union from another upazila in the same district.
      if(un)out.union=un.bn;
    }
  }
  out.ward=out.ward||ADDRESS_GEO_DATA.defaults.ward;
  out.villageBn=out.villageBn||ADDRESS_GEO_DATA.defaults.villageBn;
  out.villageEn=out.villageEn||ADDRESS_GEO_DATA.defaults.villageEn;
  out.postOfficeBn=out.postOfficeBn||ADDRESS_GEO_DATA.defaults.postOfficeBn;
  out.postOfficeEn=out.postOfficeEn||ADDRESS_GEO_DATA.defaults.postOfficeEn;
  return out;
}

function geoApplyAddresses(data,raw){
  const s=String(raw||"");
  const d=data;

  /*
    ADDRESS ROLE CONTRACT
    ---------------------
    1) Explicit "জন্মস্থান / Place of Birth" => birthPlace ONLY.
    2) Explicit "স্থায়ী ঠিকানা / Permanent Address" => permanentAddress ONLY.
    3) Explicit "বর্তমান ঠিকানা / Present Address" => presentAddress ONLY.
    4) If there is no explicit role label, but an address exists => birthPlace ONLY.
    5) If a role block is incomplete, geoCompleteAddress() fills the missing
       hierarchy from the embedded 64-district Geo Data.
    6) An explicit permanent/present block is NEVER copied to birthPlace.
  */

  const roleDefs=[
    {key:"birthPlace", re:/(?:জন্মস্থান|জন্ম\s*স্থান|place\s*of\s*birth|birth\s*place)/iu},
    {key:"permanentAddress", re:/(?:স্থায়ী\s*ঠিকানা|স্থায়ী\s*ঠিকানা|স্থায়ী\s*ঠিকানা\s*[:：]?|permanent\s*address)/iu},
    {key:"presentAddress", re:/(?:বর্তমান\s*ঠিকানা|বর্তমান\s*ঠিকানা\s*[:：]?|present\s*address)/iu}
  ];

  const allRoleRe=/(?:জন্মস্থান|জন্ম\s*স্থান|place\s*of\s*birth|birth\s*place|স্থায়ী\s*ঠিকানা|স্থায়ী\s*ঠিকানা|permanent\s*address|বর্তমান\s*ঠিকানা|present\s*address)/iu;
  const hasExplicitRole=roleDefs.some(x=>x.re.test(s));

  function roleBlock(re){
    const m=s.match(re);
    if(!m)return "";
    let tail=s.slice(m.index+m[0].length);
    tail=tail.replace(/^\s*[:：=ঃ\-–—]?\s*/u,"");
    const next=tail.search(allRoleRe);
    if(next>=0)tail=tail.slice(0,next);
    return tail.trim();
  }

  function hasUsefulAddress(v){
    const a=geoExtractAddress(v);
    return !!(a.division||a.district||a.upazila||a.union||a.ward||a.area||
      a.villageBn||a.villageEn||a.postOfficeBn||a.postOfficeEn||a.postCode||
      a.houseRoadBn||a.houseRoadEn);
  }

  // Explicit labels are authoritative. Each block is isolated before parsing,
  // so one address cannot leak into another JSON address object.
  for(const def of roleDefs){
    if(!def.re.test(s))continue;
    const block=roleBlock(def.re);
    if(!block)continue;
    d[def.key]=geoCompleteAddress(d[def.key],block,def.key);
  }

  // No explicit birth/permanent/present label: the supplied address belongs
  // to birthPlace by default. Never populate permanent/present in this case.
  if(!hasExplicitRole && hasUsefulAddress(s)){
    d.birthPlace=geoCompleteAddress(d.birthPlace,s,"birthPlace");
  }

  return d;
}
